{
  "name": "Cytomat微孔板自动培养存储系统",
  "name_en": "Cytomat Automated Microplate Incubator Storage System",
  "manufacturer": "",
  "description": "这是一种用于微孔板自动存取、培养和转运的实验室培养存储设备，带有内部存储位、传送位和外部暴露位，可控制温度、CO2、湿度和O2，并支持振荡和条码读取。常用于细胞培养、高通量筛选和自动化工作站中的板管理。",
  "description_en": "This is an automated laboratory incubator and storage system for microplates, with internal storage positions, a transfer station, and an external exposed position. It can control temperature, CO2, humidity, and O2, and supports shaking and barcode reading. It is commonly used for cell culture, high-throughput screening, and automated plate management workflows.",
  "tag_hints": [
    "automated incubator",
    "microplate storage",
    "plate handling",
    "CO2 incubation",
    "humidity control",
    "O2 control",
    "barcode reading",
    "plate shaking"
  ],
  "actions": [
    {
      "action_name": "auto-action_exposed_to_storage",
      "description": "将微孔板从外部暴露位送回存储位。",
      "description_en": "Move a microplate from the exposed external position back to storage."
    },
    {
      "action_name": "auto-action_exposed_to_wait",
      "description": "将微孔板从外部暴露位送回等待位。",
      "description_en": "Move a microplate from the exposed external position back to the wait position."
    },
    {
      "action_name": "auto-action_read_barcode",
      "description": "读取指定存储位的条码。",
      "description_en": "Read the barcode at specified storage locations."
    },
    {
      "action_name": "auto-action_storage_to_exposed",
      "description": "将微孔板从存储位送到外部暴露位。",
      "description_en": "Move a microplate from storage to the exposed external position."
    },
    {
      "action_name": "auto-action_storage_to_transfer",
      "description": "将微孔板从存储位送到传送位。",
      "description_en": "Move a microplate from storage to the transfer station."
    },
    {
      "action_name": "auto-action_storage_to_wait",
      "description": "将微孔板从存储位送到等待位。",
      "description_en": "Move a microplate from storage to the wait position."
    },
    {
      "action_name": "auto-action_transfer_to_storage",
      "description": "将微孔板从传送位移入存储位。",
      "description_en": "Move a microplate from the transfer station into storage."
    },
    {
      "action_name": "auto-action_transfer_to_wait",
      "description": "将微孔板从传送位移到等待位。",
      "description_en": "Move a microplate from the transfer station to the wait position."
    },
    {
      "action_name": "auto-action_wait_to_exposed",
      "description": "将微孔板从等待位送到外部暴露位。",
      "description_en": "Move a microplate from the wait position to the exposed external position."
    },
    {
      "action_name": "auto-action_wait_to_storage",
      "description": "将微孔板从等待位送回存储位。",
      "description_en": "Move a microplate from the wait position back to storage."
    },
    {
      "action_name": "auto-action_wait_to_transfer",
      "description": "将微孔板从等待位送到传送位。",
      "description_en": "Move a microplate from the wait position to the transfer station."
    },
    {
      "action_name": "auto-close_door",
      "description": "关闭设备门。",
      "description_en": "Close the device door."
    },
    {
      "action_name": "auto-fetch_plate_to_loading_tray",
      "description": "将指定微孔板取到上样托盘。",
      "description_en": "Fetch a specified microplate to the loading tray."
    },
    {
      "action_name": "auto-init_shakers",
      "description": "初始化内部振荡模块。",
      "description_en": "Initialize the internal shakers."
    },
    {
      "action_name": "auto-initialize",
      "description": "初始化设备。",
      "description_en": "Initialize the device."
    },
    {
      "action_name": "auto-open_door",
      "description": "打开设备门。",
      "description_en": "Open the device door."
    },
    {
      "action_name": "auto-reset_error_register",
      "description": "复位错误寄存器。",
      "description_en": "Reset the error register."
    },
    {
      "action_name": "auto-send_action",
      "description": "向设备发送动作命令并等待完成。",
      "description_en": "Send an action command to the device and wait for completion."
    },
    {
      "action_name": "auto-send_command",
      "description": "向设备发送底层命令。",
      "description_en": "Send a low-level command to the device."
    },
    {
      "action_name": "auto-serialize",
      "description": "导出设备配置或状态信息。",
      "description_en": "Export device configuration or state information."
    },
    {
      "action_name": "auto-set_racks",
      "description": "设置设备中的板架布局。",
      "description_en": "Set the rack layout installed in the device."
    },
    {
      "action_name": "auto-set_shaking_frequency",
      "description": "设置振荡频率。",
      "description_en": "Set shaking frequency."
    },
    {
      "action_name": "auto-set_temperature",
      "description": "设置温度。",
      "description_en": "Set temperature."
    },
    {
      "action_name": "auto-setup",
      "description": "准备设备以供运行。",
      "description_en": "Prepare the device for operation."
    },
    {
      "action_name": "auto-shovel_in",
      "description": "收回传送铲。",
      "description_en": "Retract the transfer shovel."
    },
    {
      "action_name": "auto-shovel_out",
      "description": "伸出传送铲。",
      "description_en": "Extend the transfer shovel."
    },
    {
      "action_name": "auto-start_shaking",
      "description": "按设定频率开始振荡。",
      "description_en": "Start shaking at the specified frequency."
    },
    {
      "action_name": "auto-stop",
      "description": "停止设备运行。",
      "description_en": "Stop device operation."
    },
    {
      "action_name": "auto-stop_shaking",
      "description": "停止振荡。",
      "description_en": "Stop shaking."
    },
    {
      "action_name": "auto-take_in_plate",
      "description": "将微孔板收入指定存储位。",
      "description_en": "Take a microplate into a specified storage position."
    },
    {
      "action_name": "auto-wait_for_task_completion",
      "description": "等待当前任务完成。",
      "description_en": "Wait for the current task to complete."
    },
    {
      "action_name": "auto-wait_for_transfer_station",
      "description": "等待传送位变为占用或空闲状态。",
      "description_en": "Wait for the transfer station to become occupied or empty."
    },
    {
      "action_name": "auto-get_overview_register",
      "description": "获取总览寄存器状态。",
      "description_en": "Get overview register state."
    },
    {
      "action_name": "auto-get_warning_register",
      "description": "获取警告寄存器状态。",
      "description_en": "Get warning register state."
    },
    {
      "action_name": "auto-get_error_register",
      "description": "获取错误寄存器状态。",
      "description_en": "Get error register state."
    },
    {
      "action_name": "auto-get_action_register",
      "description": "获取动作寄存器状态。",
      "description_en": "Get action register state."
    },
    {
      "action_name": "auto-get_swap_register",
      "description": "获取交换寄存器状态。",
      "description_en": "Get swap register state."
    },
    {
      "action_name": "auto-get_sensor_register",
      "description": "获取传感器寄存器状态。",
      "description_en": "Get sensor register state."
    },
    {
      "action_name": "auto-get_incubation_query",
      "description": "获取指定培养查询值。",
      "description_en": "Get the specified incubation query value."
    },
    {
      "action_name": "auto-get_co2",
      "description": "获取CO2浓度。",
      "description_en": "Get CO2 concentration."
    },
    {
      "action_name": "auto-get_humidity",
      "description": "获取湿度。",
      "description_en": "Get humidity."
    },
    {
      "action_name": "auto-get_o2",
      "description": "获取O2浓度。",
      "description_en": "Get O2 concentration."
    },
    {
      "action_name": "auto-get_temperature",
      "description": "获取温度。",
      "description_en": "Get temperature."
    }
  ]
}

